SELECT store_id as storeId, COUNT(id) as orderNum, IFNULL(SUM(total_amount), 0) as turnover, IFNULL(SUM(coupon_amount), 0) as offerTotal, IFNULL(SUM(item_num), 0) as itemNum FROM user_coupon_record WHERE deleted = b'0' AND coupon_id = #{couponId} AND store_id IN
#{storeId}
GROUP BY store_id
